export function captureBridge(invoke = captureBusiness()): typeof businessBindings {
  const bound = {} as typeof businessBindings;
  for (const name of Object.keys(businessBindings) as (keyof typeof businessBindings)[]) {
    const method = Native[name];
    (bound as Record<string, unknown>)[name] = name === 'QuitAppOnly' ? method : (...args: unknown[]) => invoke(method, args);
  }
  return bound;
}
